package br.com.onda;
import android.net.Uri;import java.io.*;import org.junit.Test;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class ChapterDetectionTest {
 private AudioChapterScanner.Control mode(int value){return new AudioChapterScanner.Control(){public int mode(){return value;}public void check(){}public void progress(long at,long total){}};}
 @Test public void actualNoisyPcmIsSeparatedByAdaptiveModeWithoutChangingSource()throws Exception{android.content.Context c=getInstrumentation().getTargetContext();File file=AudioTestFixtures.noisyCollection(c,false);byte[] original=java.nio.file.Files.readAllBytes(file.toPath());try{assertEquals(1,AudioChapterScanner.scan(c,Uri.fromFile(file),mode(0)).starts.size());AudioChapterScanner.Result result=AudioChapterScanner.scan(c,Uri.fromFile(file),mode(1));assertEquals(3,result.starts.size());assertEquals(32650,result.starts.get(1),300);assertEquals(65450,result.starts.get(2),300);assertArrayEquals(original,java.nio.file.Files.readAllBytes(file.toPath()));}finally{file.delete();}}
 @Test public void realShortGapsNeedSensitiveMode()throws Exception{android.content.Context c=getInstrumentation().getTargetContext();File file=AudioTestFixtures.noisyCollection(c,true);try{assertEquals(1,AudioChapterScanner.scan(c,Uri.fromFile(file),mode(1)).starts.size());assertEquals(3,AudioChapterScanner.scan(c,Uri.fromFile(file),mode(2)).starts.size());}finally{file.delete();}}
 @Test public void detectionMenuShowsAllModesAndPersistsChoice()throws Exception{android.app.Instrumentation ins=getInstrumentation();android.content.Context c=ins.getTargetContext();int old=ChapterDetection.get(c);AudioChaptersActivity screen=(AudioChaptersActivity)ins.startActivitySync(new android.content.Intent(c,AudioChaptersActivity.class).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));try{ins.waitForIdleSync();for(int attempt=0;attempt<200;attempt++){boolean[] ready={false};ins.runOnMainSync(()->{try{java.lang.reflect.Field button=AudioChaptersActivity.class.getDeclaredField("detection");button.setAccessible(true);ready[0]=((android.widget.Button)button.get(screen)).isEnabled();}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])break;Thread.sleep(50);}ins.runOnMainSync(()->{try{java.lang.reflect.Field button=AudioChaptersActivity.class.getDeclaredField("detection");button.setAccessible(true);((android.widget.Button)button.get(screen)).performClick();java.lang.reflect.Field field=AudioChaptersActivity.class.getDeclaredField("detectionDialog");field.setAccessible(true);android.app.AlertDialog dialog=(android.app.AlertDialog)field.get(screen);assertNotNull(dialog.getListView());assertTrue(dialog.getListView().isShown());assertEquals(3,dialog.getListView().getAdapter().getCount());dialog.getListView().performItemClick(null,2,2);assertEquals(2,ChapterDetection.get(c));assertTrue(((android.widget.Button)button.get(screen)).getText().toString().contains("Sensível"));}catch(Exception error){throw new RuntimeException(error);}});}finally{c.getSharedPreferences("chapter-detection",0).edit().putInt("mode",old).commit();ins.runOnMainSync(screen::finish);}}
}
